-- AUTOMATISCH ERZEUGT aus daten/ (npm run seed) – nicht von Hand bearbeiten.
-- Teil von supabase/seed.sql: Thema 36 „Leerstand und Geschäftsschließungen in Innenstädten“ – Instrumente, Maßnahmen, Prüfeinheiten, Abdeckung.
-- Nach 0-gemeinsam.sql ausführen. Mehrfach ausführbar, gespielte Runden bleiben erhalten.

begin;

delete from public.massnahmen where thema_id = 36;
delete from public.abdeckung where thema_id = 36;
delete from public.pruef_einheiten where thema_id = 36;

-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9953, 36, 'Parkraum und Fahrspuren in Innenstädten erhalten oder ausbauen, Fahrverbote ablehnen (Bund)', 'Gute Pkw-Erreichbarkeit hilft Händlern mit Kundschaft aus dem Umland; Studien zeigen aber, dass viele Kunden zu Fuß, mit Rad oder ÖPNV kommen. Zuständig sind vor allem Kommunen; der Bund setzt nur den Rahmen.', 'gemischt', 'https://findingspress.org/article/24497-local-business-perception-vs-mobility-behavior-of-shoppers-a-survey-from-berlin', 'bund', null, true, 'blind'),
  (9954, 36, 'Parkraum, Straßenkapazität, Kurzzeit- und Ladezonen für Kfz in Innenstädten sichern (Land)', 'Kurzzeitparken und Ladezonen stützen den Einzelhandel punktuell; Händler überschätzen jedoch oft den Anteil der Autokunden. Zu Zugangsbeschränkungen wie Umweltzonen ist die Wirkung auf Handelsumsätze je nach Geschäftstyp uneinheitlich.', 'gemischt', 'https://findingspress.org/article/24497-local-business-perception-vs-mobility-behavior-of-shoppers-a-survey-from-berlin', 'land', null, true, 'blind'),
  (9955, 36, 'Verkehrsberuhigung und Umverteilung von Straßenraum in Geschäftsstraßen (Land)', 'Mehr Platz und Aufenthalt für Fußgänger erhöht oft die Passantenfrequenz; Ladenbetreiber befürchten jedoch Umsatzverluste, wenn Parkplätze und Zufahrt wegfallen. Mit Lieferzonen und Baukasten lässt sich der Zugang sichern.', 'gemischt', 'https://doi.org/10.1080/01441647.2021.1912849', 'land', null, true, 'blind'),
  (9956, 36, 'Fußverkehrsinfrastruktur verbessern (Gehwege, Querungen, Barrierefreiheit, Winterdienst) (Land)', 'Bessere Fußwege erleichtern den Weg zu Geschäften, der Bezug zum Einkaufsangebot ist aber indirekt und kaum untersucht. Gut machbar über Landes- und Bezirkshaushalte.', 'offen', null, 'land', null, true, 'blind'),
  (9957, 36, 'Radverkehrsnetz und Fahrradstraßen ausbauen (Land)', 'Radkunden kaufen häufig und lokal ein, der Effekt auf Geschäftsbesatz ist aber nur indirekt; Radnetze sind kurzfristig umsetzbar. Wirkung auf Leerstand kaum belegt.', 'gemischt', 'https://doi.org/10.1080/01441647.2021.1912849', 'land', null, true, 'blind'),
  (9958, 36, 'Sichere Fahrradabstellanlagen und Fahrradparkhäuser (Land)', 'Sichere Abstellplätze erleichtern die Anreise mit dem Rad, sind aber nur eine Teilvoraussetzung für die Erreichbarkeit. Günstig und schnell umsetzbar; Wirkung auf Einkaufsangebote kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9959, 36, 'ÖPNV-Angebot ausbauen und beschleunigen (Netz, Takt, Personal, Anbindung der Innenstadt) (Land)', 'Bessere Anbindung bringt Kunden in die Zentren; ÖPNV-Kunden kommen öfter, geben je Besuch nach Kontrolle von Kundenmerkmalen aber kaum anders aus. Der Effekt auf Geschäftsbesatz ist kaum belegt. Netzausbau braucht Jahre und hohe Mittel, Personal fehlt teils.', 'offen', null, 'land', null, true, 'blind'),
  (9960, 36, 'ÖPNV-Tarifangebote und Mobilitätskonten für einfacheren Zugang (Land)', 'Einfachere Tickets und Pendlertarife senken Hürden für die Anreise in Zentren; der Beitrag zum Einkaufsangebot bleibt gering und ist kaum untersucht. Landesweit rasch umsetzbar.', 'offen', null, 'land', null, true, 'blind'),
  (9961, 36, 'Zwischennutzung leerstehender Flächen erleichtern und fördern (Land)', 'Pop-up-Läden und Zwischennutzungen beleben Leerstand und können Dauermieter anziehen; viele bleiben aber befristet und lösen strukturellen Leerstand nicht. Rechtlich und finanziell gut machbar.', 'gemischt', 'https://www.innenstadtprogramm.bund.de/SharedDocs/downloads/Webs/ZIZ/DE/Erfahrungsbericht_Zwischennutzung.pdf?__blob=publicationFile&v=4', 'land', null, true, 'blind'),
  (9962, 36, 'Abgestufte Eingriffe gegen langfristigen Leerstand (Fristen, Abgaben, Vorkaufsrecht, Übernahme) (Land)', 'Druck auf untätige Eigentümer kann Nutzung anstoßen; Erfahrungen mit Leerstandsabgaben für Gewerbe sind uneinheitlich. Eigentumsrecht und Rechtssicherheit erfordern Aufwand, Vorkaufsrechte sind teuer.', 'gemischt', 'https://wrap.warwick.ac.uk/id/eprint/171874/', 'land', null, true, 'blind'),
  (9963, 36, 'Gewerbemieten per Bundesgesetz begrenzen, Bundesratsinitiative (Land)', 'Mietbegrenzung kann Verdrängung kleiner Läden bremsen, könnte aber das Angebot an Gewerberaum verknappen; Erfahrungen sind kaum untersucht. Land kann nur im Bundesrat vorschlagen, Eigentumsgarantie ist zu beachten.', 'offen', null, 'land', null, true, 'blind'),
  (9964, 36, 'Landesförderprogramm für Umbau und Sanierung leerstehender Gebäude und Zentren (Land)', 'Förderung senkt Umbaukosten und aktiviert Leerstand; Evaluierungen ähnlicher Programme zeigen Aufwertung, aber nicht immer weniger Leerstand. Finanzierbar im Landeshaushalt, auch mit Bundesmitteln.', 'gemischt', 'https://www.staedtebaufoerderung.info/SharedDocs/downloads/DE/WeitereProgramme/AktiveStadtUndOrtsteilzentren/Zwischeneva_2015.pdf?__blob=publicationFile&v=2', 'land', null, true, 'blind'),
  (9965, 36, 'Städtebauförderung für Innenstädte und Ortszentren aufstocken (Bund)', 'Etabliertes Programm für Zentren, Aufenthaltsqualität und Nutzungsmischung; Evaluierungen sehen Aufwertung, der Rückgang von Leerstand ist weniger klar. Bund finanziert bereits, Aufstockung ist haushaltsrechtlich machbar.', 'gemischt', 'https://www.staedtebaufoerderung.info/SharedDocs/downloads/DE/WeitereProgramme/AktiveStadtUndOrtsteilzentren/Zwischeneva_2015.pdf?__blob=publicationFile&v=2', 'bund', null, true, 'blind'),
  (9966, 36, 'Umwandlung und Aufstockung leerstehender Gewerbe-, Büro- und Handelsflächen zu Wohnraum erleichtern (Land)', 'Umnutzung beseitigt Leerstand und belebt Quartiere, ersetzt aber Handelsflächen und erweitert das Einkaufsangebot nicht. Über Landesbauordnung und Genehmigungspraxis rasch machbar.', 'gemischt', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/bbsr-online/2025/bbsr-online-052-2025-dl.pdf?__blob=publicationFile&v=2', 'land', null, true, 'blind'),
  (9967, 36, 'Leerstandskataster und Flächenmonitoring einführen (Land)', 'Bessere Daten erleichtern gezielte Ansiedlung und Ansprache von Eigentümern, bewirken allein aber keine Nutzung. Geringer Aufwand, Ergebnis hängt von der Nutzung der Daten ab.', 'offen', null, 'land', null, true, 'blind'),
  (9968, 36, 'Zentren- und Citymanagement mit Kommunen, Handel und Gastronomie (Land)', 'Abgestimmte Konzepte und lokale Zusammenschlüsse (etwa Standortgemeinschaften) werden positiv bewertet, strenge Wirkungsstudien fehlen. Geringe Kosten, im Land schnell umsetzbar.', 'gemischt', 'https://www.furmancenter.org/wp-content/uploads/2007/05/ImpactofBIDcombined_000_1_1.pdf', 'land', null, true, 'blind'),
  (9969, 36, 'Strategische Innenstadt-, Zentren- und Bodenpolitik ohne konkretes Instrument (Land)', 'Leitlinien wie Innenentwicklung oder neue Zentrenpläne geben Richtung vor; konkrete Wirkung hängt von späteren Instrumenten ab und ist schwer zu belegen. Rechtlich ohne Hürden.', 'gemischt', 'https://repos.hcu-hamburg.de/handle/hcu/570', 'land', null, true, 'blind'),
  (9970, 36, 'Dorfzentren und integrierte ländliche Entwicklung fördern (Land)', 'Gebündelte Angebote im Ortskern (Dorfladen, Treffpunkte) können Grundversorgung sichern; Erfahrungen mit Dorfläden sind gemischt, flächendeckende Wirkung auf Leerstand unklar. Finanzierbar mit Landes- und EU-Mitteln.', 'gemischt', 'https://literatur.thuenen.de/digbib_extern/dn065243.pdf', 'land', null, true, 'blind'),
  (9971, 36, 'Warenhaus-Standorte erhalten und mit neuen Nutzungen füllen (Land)', 'Warenhaus-Schließungen senken die Frequenz im Umfeld (Studie: im Mittel rund 12 %), Nachnutzungen mildern den Rückgang; die Wirkung kultureller oder öffentlicher Nutzer ist kaum untersucht. Landesmittel sind begrenzt, Eigentümer und Betreiber entscheiden mit.', 'gemischt', 'https://doi.org/10.1016/j.jretai.2026.05.001', 'land', null, true, 'blind'),
  (9972, 36, 'Verkaufsoffene Sonntage ausweiten und Genehmigung vereinfachen, im bestehenden Rechtsrahmen (Land)', 'Mehr Sonntagsöffnung kann Frequenz steigern; Länderstudien finden mehr Beschäftigung und Ausgaben, für Deutschland weniger Handelsjobs nach der Liberalisierung. Wirkung auf Schließungen nicht direkt untersucht. Landesrecht, rasch änderbar; Beschäftigtenschutz beachten.', 'gemischt', 'https://cep.lse.ac.uk/pubs/download/dp1336.pdf', 'land', null, true, 'blind'),
  (9973, 36, 'Sonntagsöffnung vollständig freigeben, Ladenöffnungsrecht umfassend liberalisieren (Land)', 'Volle Freigabe könnte Kunden zusätzlich anziehen; Studien finden mehr Beschäftigung in Europa, aber weniger Handelsjobs in Deutschland, Wirkung auf Schließungen nicht direkt untersucht. Sonntagsschutz (Art. 140 GG) setzt enge Grenzen; teils Bundesrecht nötig.', 'gemischt', 'https://edoc.hu-berlin.de/18452/5152', 'land', null, true, 'blind'),
  (9974, 36, 'Zoll-, Steuer- und Plattformregeln für Online-Importe und große Plattformen verschärfen (Bund)', 'Gleichere Bedingungen für Online- und stationären Handel können Preisdruck mindern; die Wirkung auf Innenstadtläden ist kaum untersucht. Zoll und Plattformrecht liegen weitgehend bei der EU.', 'offen', null, 'bund', null, true, 'blind'),
  (9975, 36, 'Sichtbare Polizeipräsenz und Sicherheitspartnerschaften im öffentlichen Raum (Land)', 'Mehr Präsenz kann Kriminalität an Brennpunkten senken und das Sicherheitsgefühl verbessern; der Einfluss auf Passantenfrequenz und Ladenbesatz ist kaum belegt. Personalaufbau dauert.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356500/', 'land', null, true, 'blind'),
  (9976, 36, 'Illegalen Müll, Graffiti und Vandalismus kontrollieren und ahnden (Land)', 'Konsequente Kontrolle kann Verschmutzung verringern und Aufenthaltsqualität steigern; Wirkung auf Einkaufsangebote nur indirekt und kaum untersucht. Mit Personalmitteln im Land machbar.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356497/', 'land', null, true, 'blind'),
  (9977, 36, 'Reinigung, Pflege und Abfallinfrastruktur im öffentlichen Raum stärken (Land)', 'Sauberkeit gehört zu den meistgenannten Handlungsfeldern im Stadtbild, direkter Ansatz an der Aufenthaltsqualität; Belege zu Frequenz und Umsatz sind begrenzt. Über Landes- und Bezirksmittel gut machbar.', 'gemischt', 'https://pubmed.ncbi.nlm.nih.gov/41926728/', 'land', null, true, 'blind'),
  (9978, 36, 'Bürgerbeteiligung und Aktionstage für Sauberkeit (Land)', 'Aktionen stärken Bewusstsein und lokale Pflege, ersetzen aber keine dauerhafte Reinigung. Günstig und sofort umsetzbar; Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9979, 36, 'Begrünung und Zugang zu Gewässern in Innenstadtquartieren (Land)', 'Straßengrün und Wasserzugang steigern Aufenthaltsqualität und teils die Verweildauer, der Effekt auf Ladenbesatz ist jedoch schwach belegt. Über Landesplanung machbar.', 'gemischt', 'https://www.oecd.org/content/dam/oecd/en/publications/reports/2023/09/greening-high-streets-sustaining-community-centres_99cbeb33/5ebe6bb5-en.pdf', 'land', null, true, 'blind'),
  (9980, 36, 'Historische Stadtbilder bewahren, rekonstruieren und Heimatstil bei öffentlichen Bauten (Land)', 'Attraktive Stadtbilder können Besucher anziehen, der Zusammenhang mit Geschäftsschließungen ist kaum untersucht. Rekonstruktionen sind teuer und dauern Jahre.', 'offen', null, 'land', null, true, 'blind'),
  (9981, 36, 'Plätze, Straßen und Einkaufsviertel baulich umgestalten für mehr Aufenthaltsqualität (Land)', 'Umgestaltungen erhöhen Verweildauer und Frequenz, Erfahrungen aus Fußgängerzonen und Plätzen sind überwiegend positiv, aber vom Einzelfall abhängig. Planung und Bau dauern mehrere Jahre.', 'gemischt', 'https://discovery.ucl.ac.uk/1575499/1/Street%20appeal%20%28progress%20in%20planning%29%20-%20revised.pdf', 'land', null, true, 'blind'),
  (9982, 36, 'Obdachlosencamps räumen und deren Bau verhindern (Land)', 'Räumung ändert das Stadtbild sofort; eine Studie aus Denver sieht leicht weniger Kriminalität im Umkreis, aber mehr Gewaltdelikte und Gesundheitsschäden für Betroffene. Wirkung auf Einkaufsangebote nicht untersucht. Landes- und Ordnungsrecht reicht aus.', 'gemischt', 'https://pubmed.ncbi.nlm.nih.gov/39412580/', 'land', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 36 and id not in (9953, 9954, 9955, 9956, 9957, 9958, 9959, 9960, 9961, 9962, 9963, 9964, 9965, 9966, 9967, 9968, 9969, 9970, 9971, 9972, 9973, 9974, 9975, 9976, 9977, 9978, 9979, 9980, 9981, 9982);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (9983, 36, 11, null, 'Lehnt Fahrverbote für Innenstädte und das Umwidmen von Parkplätzen ab.', '{3604}', 9953, 1, 2, null, 'Gute Pkw-Erreichbarkeit hilft Händlern mit Kundschaft aus dem Umland; Studien zeigen aber, dass viele Kunden zu Fuß, mit Rad oder ÖPNV kommen. Zuständig sind vor allem Kommunen; der Bund setzt nur den Rahmen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', 'https://findingspress.org/article/24497-local-business-perception-vs-mobility-behavior-of-shoppers-a-survey-from-berlin', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9984, 36, 11, null, 'Bürokratie für den Einzelhandel verringern: Beweislast bei Dokumentationspflichten umkehren, regelmäßige Nachweise durch ein Anzeigerecht ersetzen.', '{3601}', null, 1, 3, null, 'Weniger Dokumentationsaufwand entlastet stationäre Händler, Größe des Effekts auf Schließungen ist kaum untersucht. Bundesrechtlich machbar, Beweislastumkehr braucht Prüfung der Schutzziele.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=17', null, 'offen', '2026-10-14', false, true, 'blind'),
  (9985, 36, 11, 'BE', 'Förderprogramm für den Umbau von Handelsimmobilien zu Wohn-, Büro- und Kulturnutzungen; Zentrenprogramm „Lebendige Zentren“ mit dem Bund um- und ausbauen', '{3602}', 9964, 2, 3, null, 'Förderung senkt Umbaukosten und aktiviert Leerstand; Evaluierungen ähnlicher Programme zeigen Aufwertung, aber nicht immer weniger Leerstand. Finanzierbar im Landeshaushalt, auch mit Bundesmitteln.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=37', 'https://www.staedtebaufoerderung.info/SharedDocs/downloads/DE/WeitereProgramme/AktiveStadtUndOrtsteilzentren/Zwischeneva_2015.pdf?__blob=publicationFile&v=2', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9986, 36, 11, 'BE', 'Leerstandsmanagement landeseigener Immobilien weiterentwickeln und für Start-ups und Kreativwirtschaft öffnen', '{3602}', 9961, 2, 3, null, 'Pop-up-Läden und Zwischennutzungen beleben Leerstand und können Dauermieter anziehen; viele bleiben aber befristet und lösen strukturellen Leerstand nicht. Rechtlich und finanziell gut machbar.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=37', 'https://www.innenstadtprogramm.bund.de/SharedDocs/downloads/Webs/ZIZ/DE/Erfahrungsbericht_Zwischennutzung.pdf?__blob=publicationFile&v=4', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9987, 36, 11, 'BE', 'Systematisches Leerstandsmonitoring von Büro- und Gewerbeflächen einführen', '{3602}', 9967, 1, 3, null, 'Bessere Daten erleichtern gezielte Ansiedlung und Ansprache von Eigentümern, bewirken allein aber keine Nutzung. Geringer Aufwand, Ergebnis hängt von der Nutzung der Daten ab.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=37', null, 'offen', '2026-10-14', false, true, 'blind'),
  (9988, 36, 11, 'BE', 'Engen Austausch mit den Bezirken suchen und den Zentrengipfel gegen Leerstand fortführen', '{3602}', 9968, 2, 3, null, 'Abgestimmte Konzepte und lokale Zusammenschlüsse (etwa Standortgemeinschaften) werden positiv bewertet, strenge Wirkungsstudien fehlen. Geringe Kosten, im Land schnell umsetzbar.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=37', 'https://www.furmancenter.org/wp-content/uploads/2007/05/ImpactofBIDcombined_000_1_1.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9989, 36, 11, 'BE', 'Konkrete Kiezpläne für jede Einkaufsstraße gemeinsam mit Bezirken, Handel und Gastronomie entwickeln', '{3602}', 9968, 2, 3, null, 'Abgestimmte Konzepte und lokale Zusammenschlüsse (etwa Standortgemeinschaften) werden positiv bewertet, strenge Wirkungsstudien fehlen. Geringe Kosten, im Land schnell umsetzbar.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=37', 'https://www.furmancenter.org/wp-content/uploads/2007/05/ImpactofBIDcombined_000_1_1.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9990, 36, 11, 'BE', 'Rechtssichere Sonntagsöffnung; acht verkaufsoffene Sonntage sollen stattfinden; Bezirke sollen zweimal im Jahr zusätzliche verkaufsoffene Sonntage festlegen können', '{3604}', 9972, 1, 3, null, 'Mehr Sonntagsöffnung kann Frequenz steigern; Länderstudien finden mehr Beschäftigung und Ausgaben, für Deutschland weniger Handelsjobs nach der Liberalisierung. Wirkung auf Schließungen nicht direkt untersucht. Landesrecht, rasch änderbar; Beschäftigtenschutz beachten.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=37', 'https://cep.lse.ac.uk/pubs/download/dp1336.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9991, 36, 11, 'BE', 'Baukasten für Bezirke zu Verkehrsberuhigung und Verkehrssicherheit, damit wohnungsnaher Einzelhandel für Kunden erreichbar bleibt', '{3604}', 9955, 2, 3, null, 'Mehr Platz und Aufenthalt für Fußgänger erhöht oft die Passantenfrequenz; Ladenbetreiber befürchten jedoch Umsatzverluste, wenn Parkplätze und Zufahrt wegfallen. Mit Lieferzonen und Baukasten lässt sich der Zugang sichern.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=70', 'https://doi.org/10.1080/01441647.2021.1912849', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9992, 36, 11, 'BE', 'Verkehrsinfrastruktur gezielt ergänzen, um Innenstadt und Außenbezirke besser zu vernetzen', '{3604}', 9959, 1, 2, null, 'Bessere Anbindung bringt Kunden in die Zentren; ÖPNV-Kunden kommen öfter, geben je Besuch nach Kontrolle von Kundenmerkmalen aber kaum anders aus. Der Effekt auf Geschäftsbesatz ist kaum belegt. Netzausbau braucht Jahre und hohe Mittel, Personal fehlt teils.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=69', null, 'offen', '2026-10-14', false, true, 'blind'),
  (9993, 36, 11, 'BE', 'Taubenpopulation an Einkaufszentren und anderen stark frequentierten Orten begrenzen (Taubenschläge, Fütterungsverbote, bauliche Vergrämung)', '{3603}', 9977, 2, 3, null, 'Sauberkeit gehört zu den meistgenannten Handlungsfeldern im Stadtbild, direkter Ansatz an der Aufenthaltsqualität; Belege zu Frequenz und Umsatz sind begrenzt. Über Landes- und Bezirksmittel gut machbar.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=79', 'https://pubmed.ncbi.nlm.nih.gov/41926728/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9994, 36, 11, 'MV', 'Regeln für verkaufsoffene Sonntage praxisnäher und flexibler gestalten und dafür bürokratische Hürden abbauen.', '{3604}', 9972, 1, 3, null, 'Mehr Sonntagsöffnung kann Frequenz steigern; Länderstudien finden mehr Beschäftigung und Ausgaben, für Deutschland weniger Handelsjobs nach der Liberalisierung. Wirkung auf Schließungen nicht direkt untersucht. Landesrecht, rasch änderbar; Beschäftigtenschutz beachten.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=23', 'https://cep.lse.ac.uk/pubs/download/dp1336.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9995, 36, 11, 'MV', 'Integrierte ländliche Entwicklung fördern, auch um Leerstand zu revitalisieren und mit Wohnen und Freizeit zu verbinden.', '{3602}', 9970, 1, 3, null, 'Gebündelte Angebote im Ortskern (Dorfladen, Treffpunkte) können Grundversorgung sichern; Erfahrungen mit Dorfläden sind gemischt, flächendeckende Wirkung auf Leerstand unklar. Finanzierbar mit Landes- und EU-Mitteln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=122', 'https://literatur.thuenen.de/digbib_extern/dn065243.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9996, 36, 11, 'MV', 'Mehr Polizei in Innenstädten und an Kriminalitätsschwerpunkten, höherer Kontrolldruck, wirksamere Platzverweise und Aufenthaltsverbote für mehr Ordnung im öffentlichen Raum.', '{3603}', 9975, 1, 2, null, 'Mehr Präsenz kann Kriminalität an Brennpunkten senken und das Sicherheitsgefühl verbessern; der Einfluss auf Passantenfrequenz und Ladenbesatz ist kaum belegt. Personalaufbau dauert.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=31', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356500/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9997, 36, 11, 'ST', 'Einzelhandel in Innenstädten gezielt unterstützen, kreative Konzepte gegen Leerstand verfolgen und Stadtkerne als Orte der Begegnung stärken.', '{3602,3603}', 9969, 1, 3, null, 'Leitlinien wie Innenentwicklung oder neue Zentrenpläne geben Richtung vor; konkrete Wirkung hängt von späteren Instrumenten ab und ist schwer zu belegen. Rechtlich ohne Hürden.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=66', 'https://repos.hcu-hamburg.de/handle/hcu/570', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9998, 36, 11, 'ST', 'Überholte Umweltzonen in Innenstädten aufheben.', '{3604}', 9954, 1, 3, null, 'Kurzzeitparken und Ladezonen stützen den Einzelhandel punktuell; Händler überschätzen jedoch oft den Anteil der Autokunden. Zu Zugangsbeschränkungen wie Umweltzonen ist die Wirkung auf Handelsumsätze je nach Geschäftstyp uneinheitlich.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=62', 'https://findingspress.org/article/24497-local-business-perception-vs-mobility-behavior-of-shoppers-a-survey-from-berlin', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9999, 36, 12, null, 'Leerstand-Strategie mit Förderprogrammen, damit leerstehende Immobilien zu Wohn- oder Gewerberaum werden', '{3602}', null, 2, 3, null, 'Förderprogramme und Anreize für Umnutzung leerstehender Gebäude senken Hürden für Eigentümer und Kommunen; Evaluierungen ähnlicher Programme zeigen Aufwertung, aber nicht durchgehend weniger Leerstand. Bund kann es finanzieren.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=53', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10000, 36, 12, 'BE', 'Leerstehende Ladenzeilen und Shoppingcenter beleben, Zwischennutzungen fördern und Genehmigungen vereinfachen.', '{3602}', 9961, 2, 3, null, 'Pop-up-Läden und Zwischennutzungen beleben Leerstand und können Dauermieter anziehen; viele bleiben aber befristet und lösen strukturellen Leerstand nicht. Rechtlich und finanziell gut machbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=19', 'https://www.innenstadtprogramm.bund.de/SharedDocs/downloads/Webs/ZIZ/DE/Erfahrungsbericht_Zwischennutzung.pdf?__blob=publicationFile&v=4', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10001, 36, 12, 'BE', 'Empfehlungen des Zentrengipfels zur Attraktivität von Einkaufsstraßen umsetzen, lokale Selbstorganisation stärken.', '{3602}', 9968, 2, 3, null, 'Abgestimmte Konzepte und lokale Zusammenschlüsse (etwa Standortgemeinschaften) werden positiv bewertet, strenge Wirkungsstudien fehlen. Geringe Kosten, im Land schnell umsetzbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=13', 'https://www.furmancenter.org/wp-content/uploads/2007/05/ImpactofBIDcombined_000_1_1.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10002, 36, 12, 'BE', 'Neues Stadtquartier am Molkenmarkt mit Wohnungen, Gewerbe und Kultur zügig errichten.', '{3602}', null, 1, 2, null, 'Ein gemischtes Quartier mit Gewerbe und Kultur ergänzt die Innenstadt, betrifft aber nur einen Standort. Bau dauert Jahre, Finanzierung über landeseigene Gesellschaften.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=19', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10003, 36, 12, 'BE', 'Mehr Ladezonen und Kurzzeitparkplätze in Geschäftsstraßen.', '{3604}', 9954, 1, 3, null, 'Kurzzeitparken und Ladezonen stützen den Einzelhandel punktuell; Händler überschätzen jedoch oft den Anteil der Autokunden. Zu Zugangsbeschränkungen wie Umweltzonen ist die Wirkung auf Handelsumsätze je nach Geschäftstyp uneinheitlich.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=27', 'https://findingspress.org/article/24497-local-business-perception-vs-mobility-behavior-of-shoppers-a-survey-from-berlin', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10004, 36, 12, 'BE', 'Flächendeckend mindestens 10-Minuten-Takt im ÖPNV, auch in der Innenstadt.', '{3604}', 9959, 1, 2, null, 'Bessere Anbindung bringt Kunden in die Zentren; ÖPNV-Kunden kommen öfter, geben je Besuch nach Kontrolle von Kundenmerkmalen aber kaum anders aus. Der Effekt auf Geschäftsbesatz ist kaum belegt. Netzausbau braucht Jahre und hohe Mittel, Personal fehlt teils.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=24', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10005, 36, 12, 'BE', 'Bundesgesetze für bezahlbare Gewerbemieten anstoßen; Gewerbemix in Kiezen gegen Verdrängung erhalten.', '{3602}', 9963, 1, 1, null, 'Mietbegrenzung kann Verdrängung kleiner Läden bremsen, könnte aber das Angebot an Gewerberaum verknappen; Erfahrungen sind kaum untersucht. Land kann nur im Bundesrat vorschlagen, Eigentumsgarantie ist zu beachten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=13', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10006, 36, 12, 'BE', 'Plätze und Straßen so gestalten, dass Menschen gern verweilen und sich sicher fühlen.', '{3603}', 9981, 2, 2, null, 'Umgestaltungen erhöhen Verweildauer und Frequenz, Erfahrungen aus Fußgängerzonen und Plätzen sind überwiegend positiv, aber vom Einzelfall abhängig. Planung und Bau dauern mehrere Jahre.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=22', 'https://discovery.ucl.ac.uk/1575499/1/Street%20appeal%20%28progress%20in%20planning%29%20-%20revised.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10007, 36, 12, 'BE', 'Straßenreinigungsgesetz ändern, damit die BSR Sauberkeit über Meldungen, Sensoren und Feedback steuern kann.', '{3603}', 9977, 2, 3, null, 'Sauberkeit gehört zu den meistgenannten Handlungsfeldern im Stadtbild, direkter Ansatz an der Aufenthaltsqualität; Belege zu Frequenz und Umsatz sind begrenzt. Über Landes- und Bezirksmittel gut machbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=24', 'https://pubmed.ncbi.nlm.nih.gov/41926728/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10008, 36, 12, 'BE', 'Sicherheit im öffentlichen Raum stärken: Beleuchtung und Überdachung von Haltestellen, besetzte Bahnhöfe, BVG-Streifen.', '{3603}', 9975, 1, 2, null, 'Mehr Präsenz kann Kriminalität an Brennpunkten senken und das Sicherheitsgefühl verbessern; der Einfluss auf Passantenfrequenz und Ladenbesatz ist kaum belegt. Personalaufbau dauert.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356500/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10009, 36, 12, 'BE', 'Breitere, beleuchtete, barrierefreie Gehwege und mehr sichere Querungen fördern.', '{3604}', 9956, 1, 3, null, 'Bessere Fußwege erleichtern den Weg zu Geschäften, der Bezug zum Einkaufsangebot ist aber indirekt und kaum untersucht. Gut machbar über Landes- und Bezirkshaushalte.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=25', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10010, 36, 12, 'BE', 'Gewässer in der Innenstadt besser zugänglich machen, Baden in der Spree ermöglichen.', '{3603}', 9979, 1, 3, null, 'Straßengrün und Wasserzugang steigern Aufenthaltsqualität und teils die Verweildauer, der Effekt auf Ladenbesatz ist jedoch schwach belegt. Über Landesplanung machbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=23', 'https://www.oecd.org/content/dam/oecd/en/publications/reports/2023/09/greening-high-streets-sustaining-community-centres_99cbeb33/5ebe6bb5-en.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10011, 36, 12, 'MV', 'Kooperation von Kultur und Tourismus stärken, um Innenstädte mit Kulturrouten, Festivals und Kunst im öffentlichen Raum zu beleben.', '{3603}', null, 1, 3, null, 'Kulturrouten, Festivals und Kunst bringen zeitweise Frequenz, ersetzen aber kein dauerhaftes Einkaufsangebot; Wirkung auf Leerstand kaum untersucht. Günstig und schnell machbar.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=80', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10012, 36, 12, 'ST', 'Gemeinsame Initiativen von Kommunen und Wirtschaft sollen Stadt- und Ortszentren stärken.', '{3602}', 9968, 2, 3, null, 'Abgestimmte Konzepte und lokale Zusammenschlüsse (etwa Standortgemeinschaften) werden positiv bewertet, strenge Wirkungsstudien fehlen. Geringe Kosten, im Land schnell umsetzbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=6', 'https://www.furmancenter.org/wp-content/uploads/2007/05/ImpactofBIDcombined_000_1_1.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10013, 36, 13, null, 'Städtebauförderung aufstocken, um lebendige Innenstädte und Ortszentren mit gemischten Quartieren zu schaffen', '{3602,3603}', 9965, 2, 3, null, 'Etabliertes Programm für Zentren, Aufenthaltsqualität und Nutzungsmischung; Evaluierungen sehen Aufwertung, der Rückgang von Leerstand ist weniger klar. Bund finanziert bereits, Aufstockung ist haushaltsrechtlich machbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=73', 'https://www.staedtebaufoerderung.info/SharedDocs/downloads/DE/WeitereProgramme/AktiveStadtUndOrtsteilzentren/Zwischeneva_2015.pdf?__blob=publicationFile&v=2', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10014, 36, 13, null, 'Große Onlineplattformen sollen wie der Laden um die Ecke Produktverantwortung übernehmen', '{3601}', 9974, 1, 1, null, 'Gleichere Bedingungen für Online- und stationären Handel können Preisdruck mindern; die Wirkung auf Innenstadtläden ist kaum untersucht. Zoll und Plattformrecht liegen weitgehend bei der EU.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=27', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10015, 36, 13, null, 'Zollschlupflöcher schließen, über die Onlinehändler unsichere Billigprodukte einführen', '{3601}', 9974, 1, 1, null, 'Gleichere Bedingungen für Online- und stationären Handel können Preisdruck mindern; die Wirkung auf Innenstadtläden ist kaum untersucht. Zoll und Plattformrecht liegen weitgehend bei der EU.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=29', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10016, 36, 13, 'BE', 'Sofortprogramm: leerstehende Erdgeschossflächen an soziale Träger und Initiativen zu gedeckelten Mieten vergeben', '{3602}', null, 1, 2, null, 'Gedeckelte Mieten für soziale Träger füllen Leerstand mit Nutzern, schaffen aber kein Handelsangebot; nur landeseigene oder angemietete Flächen erreichbar. Wirkung kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=56', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10017, 36, 13, 'BE', 'Landesweites Flächenregister, das unter anderem Leerstand erfasst', '{3602}', 9967, 1, 3, null, 'Bessere Daten erleichtern gezielte Ansiedlung und Ansprache von Eigentümern, bewirken allein aber keine Nutzung. Geringer Aufwand, Ergebnis hängt von der Nutzung der Daten ab.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=60', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10018, 36, 13, 'BE', 'Begrünung und Kühlung der Wohnumfelder in dicht bebauten Kiezen; in der Innenstadt Biotopflächenfaktor', '{3603}', 9979, 1, 3, null, 'Straßengrün und Wasserzugang steigern Aufenthaltsqualität und teils die Verweildauer, der Effekt auf Ladenbesatz ist jedoch schwach belegt. Über Landesplanung machbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=64', 'https://www.oecd.org/content/dam/oecd/en/publications/reports/2023/09/greening-high-streets-sustaining-community-centres_99cbeb33/5ebe6bb5-en.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10019, 36, 13, 'BE', 'Rahmen für verkaufsoffene Sonntage ausschöpfen, Schutz der Beschäftigten im Einzelhandel wahren', '{3604}', 9972, 1, 3, null, 'Mehr Sonntagsöffnung kann Frequenz steigern; Länderstudien finden mehr Beschäftigung und Ausgaben, für Deutschland weniger Handelsjobs nach der Liberalisierung. Wirkung auf Schließungen nicht direkt untersucht. Landesrecht, rasch änderbar; Beschäftigtenschutz beachten.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=102', 'https://cep.lse.ac.uk/pubs/download/dp1336.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10020, 36, 13, 'MV', 'Leerstand kommunal managen (Leerstands- und Brachflächenmanagement) und temporäre Zwischennutzungen fördern.', '{3602}', 9961, 2, 3, null, 'Pop-up-Läden und Zwischennutzungen beleben Leerstand und können Dauermieter anziehen; viele bleiben aber befristet und lösen strukturellen Leerstand nicht. Rechtlich und finanziell gut machbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=52', 'https://www.innenstadtprogramm.bund.de/SharedDocs/downloads/Webs/ZIZ/DE/Erfahrungsbericht_Zwischennutzung.pdf?__blob=publicationFile&v=4', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10021, 36, 13, 'MV', 'Umwandlung leerstehender Gewerberäume in Wohnraum erleichtern (zusammen mit Dachaufstockungen und Ausbauten).', '{3602}', 9966, 1, 3, null, 'Umnutzung beseitigt Leerstand und belebt Quartiere, ersetzt aber Handelsflächen und erweitert das Einkaufsangebot nicht. Über Landesbauordnung und Genehmigungspraxis rasch machbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=52', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/bbsr-online/2025/bbsr-online-052-2025-dl.pdf?__blob=publicationFile&v=2', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10022, 36, 13, 'MV', 'Landeswohnraumförderung aufstocken und reformieren, unter anderem um Leerstand in zentralen Ortslagen zu aktivieren.', '{3602}', 9964, 2, 3, null, 'Förderung senkt Umbaukosten und aktiviert Leerstand; Evaluierungen ähnlicher Programme zeigen Aufwertung, aber nicht immer weniger Leerstand. Finanzierbar im Landeshaushalt, auch mit Bundesmitteln.', 'https://gruene-mv.de/?wpdmdl=33772#page=53', 'https://www.staedtebaufoerderung.info/SharedDocs/downloads/DE/WeitereProgramme/AktiveStadtUndOrtsteilzentren/Zwischeneva_2015.pdf?__blob=publicationFile&v=2', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10023, 36, 13, 'MV', 'Landesprogramme für Bestandsimmobilien auflegen, um Dorfkerne zu beleben und alte Gebäude zu sanieren.', '{3602}', 9964, 2, 3, null, 'Förderung senkt Umbaukosten und aktiviert Leerstand; Evaluierungen ähnlicher Programme zeigen Aufwertung, aber nicht immer weniger Leerstand. Finanzierbar im Landeshaushalt, auch mit Bundesmitteln.', 'https://gruene-mv.de/?wpdmdl=33772#page=53', 'https://www.staedtebaufoerderung.info/SharedDocs/downloads/DE/WeitereProgramme/AktiveStadtUndOrtsteilzentren/Zwischeneva_2015.pdf?__blob=publicationFile&v=2', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10024, 36, 13, 'MV', 'Bodenpolitik so ausrichten, dass bezahlbares Wohnen mit der Wiederbelebung zentraler Ortslagen verbunden wird.', '{3602}', 9969, 1, 3, null, 'Leitlinien wie Innenentwicklung oder neue Zentrenpläne geben Richtung vor; konkrete Wirkung hängt von späteren Instrumenten ab und ist schwer zu belegen. Rechtlich ohne Hürden.', 'https://gruene-mv.de/?wpdmdl=33772#page=54', 'https://repos.hcu-hamburg.de/handle/hcu/570', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10025, 36, 13, 'ST', 'Kommunen beim Leerstandsabbau unterstützen und Zwischennutzungen, etwa durch Start-ups oder Pop-up-Stores, ermöglichen.', '{3602}', 9961, 2, 3, null, 'Pop-up-Läden und Zwischennutzungen beleben Leerstand und können Dauermieter anziehen; viele bleiben aber befristet und lösen strukturellen Leerstand nicht. Rechtlich und finanziell gut machbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=93', 'https://www.innenstadtprogramm.bund.de/SharedDocs/downloads/Webs/ZIZ/DE/Erfahrungsbericht_Zwischennutzung.pdf?__blob=publicationFile&v=4', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10026, 36, 13, 'ST', 'Kommunen mit abgestuften Instrumenten gegen langfristigen Leerstand ausstatten: Nutzungs- oder Sanierungsfristen, höhere Abgaben, verpflichtende Zwischennutzung.', '{3602}', 9962, 1, 2, null, 'Druck auf untätige Eigentümer kann Nutzung anstoßen; Erfahrungen mit Leerstandsabgaben für Gewerbe sind uneinheitlich. Eigentumsrecht und Rechtssicherheit erfordern Aufwand, Vorkaufsrechte sind teuer.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=98', 'https://wrap.warwick.ac.uk/id/eprint/171874/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10027, 36, 13, 'ST', 'Übernahme langjährig ungenutzter oder entwicklungsfähiger Immobilien als letztes Mittel erleichtern, wenn die anderen Instrumente erfolglos bleiben.', '{3602}', 9962, 1, 2, null, 'Druck auf untätige Eigentümer kann Nutzung anstoßen; Erfahrungen mit Leerstandsabgaben für Gewerbe sind uneinheitlich. Eigentumsrecht und Rechtssicherheit erfordern Aufwand, Vorkaufsrechte sind teuer.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=98', 'https://wrap.warwick.ac.uk/id/eprint/171874/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10028, 36, 13, 'ST', 'Neue moderne Dorfzentren ermöglichen, die Angebote wie Dorfladen, Co-Working und Veranstaltungsräume unter einem Dach bündeln.', '{3602}', 9970, 1, 3, null, 'Gebündelte Angebote im Ortskern (Dorfladen, Treffpunkte) können Grundversorgung sichern; Erfahrungen mit Dorfläden sind gemischt, flächendeckende Wirkung auf Leerstand unklar. Finanzierbar mit Landes- und EU-Mitteln.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=39', 'https://literatur.thuenen.de/digbib_extern/dn065243.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10029, 36, 14, null, 'Regeln, damit importierte Waren auf großen Online-Plattformen angemessen verzollt und versteuert werden.', '{3601}', 9974, 1, 1, null, 'Gleichere Bedingungen für Online- und stationären Handel können Preisdruck mindern; die Wirkung auf Innenstadtläden ist kaum untersucht. Zoll und Plattformrecht liegen weitgehend bei der EU.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=16', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10030, 36, 14, 'BE', 'Aufstockung von Einzelhandelsflächen mit Wohngeschossen unbürokratisch ermöglichen und fördern', '{3602}', 9966, 1, 3, null, 'Umnutzung beseitigt Leerstand und belebt Quartiere, ersetzt aber Handelsflächen und erweitert das Einkaufsangebot nicht. Über Landesbauordnung und Genehmigungspraxis rasch machbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=40', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/bbsr-online/2025/bbsr-online-052-2025-dl.pdf?__blob=publicationFile&v=2', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10031, 36, 14, 'BE', 'Leerstehende Gewerbe-, Büro- und Ladenflächen freiwillig in Wohnraum umwandeln ermöglichen', '{3602}', 9966, 1, 3, null, 'Umnutzung beseitigt Leerstand und belebt Quartiere, ersetzt aber Handelsflächen und erweitert das Einkaufsangebot nicht. Über Landesbauordnung und Genehmigungspraxis rasch machbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=46', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/bbsr-online/2025/bbsr-online-052-2025-dl.pdf?__blob=publicationFile&v=2', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10032, 36, 14, 'BE', 'Sondernutzungsflächen für Einzelhandel, Schankbetriebe und Kultur unbürokratisch ausweisen', '{3602,3603}', null, 1, 3, null, 'Unbürokratische Sondernutzung belebt Straßenraum mit Läden, Gastronomie und Kultur, ersetzt aber keine fehlenden Angebote. Verwaltungsvereinfachung ist im Land rasch möglich; Nutzungskonflikte (Lärm) sind zu beachten.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=28', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10033, 36, 14, 'BE', 'Quadratmetergrenzen für großflächigen Einzelhandel im Baurecht des Bundes deutlich anheben', '{3602}', null, 0, 1, null, 'Höhere Grenzen für großflächigen Einzelhandel erleichtern Standorte außerhalb der Zentren und können Innenstädte schwächen; geplante Neugestaltung moderner Standorte könnte auch Zentren helfen. Regelung liegt im Bundesbaurecht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=28', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10034, 36, 14, 'BE', 'Zwischennutzung leer stehender Gebäude erleichtern', '{3602}', 9961, 2, 3, null, 'Pop-up-Läden und Zwischennutzungen beleben Leerstand und können Dauermieter anziehen; viele bleiben aber befristet und lösen strukturellen Leerstand nicht. Rechtlich und finanziell gut machbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=34', 'https://www.innenstadtprogramm.bund.de/SharedDocs/downloads/Webs/ZIZ/DE/Erfahrungsbericht_Zwischennutzung.pdf?__blob=publicationFile&v=4', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10035, 36, 14, 'BE', 'Kleinteilige Eigentümerstruktur in der Innenstadt anstreben, wo Flächen neu gebaut oder umgestaltet werden', '{3602}', null, 1, 2, null, 'Kleinteilige Eigentümer können Vielfalt und Ansiedlung fördern, belegt ist das kaum; wirkt nur bei Neubau und Umgestaltung, daher langsam. Nur auf eigenen oder planbaren Flächen umsetzbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=36', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10036, 36, 14, 'BE', 'Leerstehende Objekte durch finanziellen Druck auf untätige Eigentümer nutzbar machen', '{3602}', 9962, 1, 2, null, 'Druck auf untätige Eigentümer kann Nutzung anstoßen; Erfahrungen mit Leerstandsabgaben für Gewerbe sind uneinheitlich. Eigentumsrecht und Rechtssicherheit erfordern Aufwand, Vorkaufsrechte sind teuer.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=41', 'https://wrap.warwick.ac.uk/id/eprint/171874/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10037, 36, 14, 'BE', 'Bauliche Umgestaltung einzelhandelsgeprägter Viertel zur Erhöhung der Aufenthaltsqualität', '{3603}', 9981, 2, 2, null, 'Umgestaltungen erhöhen Verweildauer und Frequenz, Erfahrungen aus Fußgängerzonen und Plätzen sind überwiegend positiv, aber vom Einzelfall abhängig. Planung und Bau dauern mehrere Jahre.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=28', 'https://discovery.ucl.ac.uk/1575499/1/Street%20appeal%20%28progress%20in%20planning%29%20-%20revised.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10038, 36, 14, 'BE', 'Mittel für die Pflege von Parks, Straßen und Plätzen im Land und in den Bezirken erhöhen', '{3603}', 9977, 2, 3, null, 'Sauberkeit gehört zu den meistgenannten Handlungsfeldern im Stadtbild, direkter Ansatz an der Aufenthaltsqualität; Belege zu Frequenz und Umsatz sind begrenzt. Über Landes- und Bezirksmittel gut machbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=70', 'https://pubmed.ncbi.nlm.nih.gov/41926728/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10039, 36, 14, 'BE', 'Ordnungsämter sollen Überwachung illegaler Müllentsorgung priorisieren; zusätzliche Stellen im Ordnungsdienst', '{3603}', 9976, 1, 3, null, 'Konsequente Kontrolle kann Verschmutzung verringern und Aufenthaltsqualität steigern; Wirkung auf Einkaufsangebote nur indirekt und kaum untersucht. Mit Personalmitteln im Land machbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=71', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356497/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10040, 36, 14, 'BE', 'Öffentliche Toiletten für alle Geschlechter kostenfrei nutzbar machen', '{3603}', 9977, 2, 3, null, 'Sauberkeit gehört zu den meistgenannten Handlungsfeldern im Stadtbild, direkter Ansatz an der Aufenthaltsqualität; Belege zu Frequenz und Umsatz sind begrenzt. Über Landes- und Bezirksmittel gut machbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=70', 'https://pubmed.ncbi.nlm.nih.gov/41926728/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10041, 36, 14, 'BE', 'Reinigung von ÖPNV-Verkehrsflächen und Bahnhofsvorplätzen über Verkehrsverträge sichern', '{3603}', 9977, 2, 3, null, 'Sauberkeit gehört zu den meistgenannten Handlungsfeldern im Stadtbild, direkter Ansatz an der Aufenthaltsqualität; Belege zu Frequenz und Umsatz sind begrenzt. Über Landes- und Bezirksmittel gut machbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=72', 'https://pubmed.ncbi.nlm.nih.gov/41926728/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10042, 36, 14, 'BE', 'Digitale Fahrwegplanung für Reinigungsintervalle, zunächst an Bahnhöfen', '{3603}', 9977, 2, 3, null, 'Sauberkeit gehört zu den meistgenannten Handlungsfeldern im Stadtbild, direkter Ansatz an der Aufenthaltsqualität; Belege zu Frequenz und Umsatz sind begrenzt. Über Landes- und Bezirksmittel gut machbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=71', 'https://pubmed.ncbi.nlm.nih.gov/41926728/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10043, 36, 14, 'BE', 'Polizeipräsenz im öffentlichen Raum dauerhaft verstärken', '{3603}', 9975, 1, 2, null, 'Mehr Präsenz kann Kriminalität an Brennpunkten senken und das Sicherheitsgefühl verbessern; der Einfluss auf Passantenfrequenz und Ladenbesatz ist kaum belegt. Personalaufbau dauert.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=66', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356500/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10044, 36, 14, 'BE', 'Bau von Obdachlosencamps verhindern', '{3603}', 9982, 1, 3, null, 'Räumung ändert das Stadtbild sofort; eine Studie aus Denver sieht leicht weniger Kriminalität im Umkreis, aber mehr Gewaltdelikte und Gesundheitsschäden für Betroffene. Wirkung auf Einkaufsangebote nicht untersucht. Landes- und Ordnungsrecht reicht aus.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=67', 'https://pubmed.ncbi.nlm.nih.gov/39412580/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10045, 36, 14, 'BE', 'Konsequentes Vorgehen gegen Vandalismus und Graffiti auf öffentlicher Infrastruktur', '{3603}', 9976, 1, 3, null, 'Konsequente Kontrolle kann Verschmutzung verringern und Aufenthaltsqualität steigern; Wirkung auf Einkaufsangebote nur indirekt und kaum untersucht. Mit Personalmitteln im Land machbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356497/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10046, 36, 14, 'BE', 'BSR-Kieztage öfter und an mehr Orten veranstalten', '{3603}', 9978, 1, 3, null, 'Aktionen stärken Bewusstsein und lokale Pflege, ersetzen aber keine dauerhafte Reinigung. Günstig und sofort umsetzbar; Wirkung kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=71', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10047, 36, 14, 'BE', 'Kapazität bestehender Durchgangsstraßen in der Innenstadt nicht weiter reduzieren', '{3604}', 9954, 1, 3, null, 'Kurzzeitparken und Ladezonen stützen den Einzelhandel punktuell; Händler überschätzen jedoch oft den Anteil der Autokunden. Zu Zugangsbeschränkungen wie Umweltzonen ist die Wirkung auf Handelsumsätze je nach Geschäftstyp uneinheitlich.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=62', 'https://findingspress.org/article/24497-local-business-perception-vs-mobility-behavior-of-shoppers-a-survey-from-berlin', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10048, 36, 14, 'BE', 'U-Bahn-Netz jährlich um ein bis zwei Kilometer erweitern', '{3604}', 9959, 1, 2, null, 'Bessere Anbindung bringt Kunden in die Zentren; ÖPNV-Kunden kommen öfter, geben je Besuch nach Kontrolle von Kundenmerkmalen aber kaum anders aus. Der Effekt auf Geschäftsbesatz ist kaum belegt. Netzausbau braucht Jahre und hohe Mittel, Personal fehlt teils.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=57', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10049, 36, 14, 'BE', 'Gehwegfreihaltung von parkenden Autos und Hindernissen durch konsequente Ahndung', '{3604}', 9956, 1, 3, null, 'Bessere Fußwege erleichtern den Weg zu Geschäften, der Bezug zum Einkaufsangebot ist aber indirekt und kaum untersucht. Gut machbar über Landes- und Bezirkshaushalte.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=61', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10050, 36, 14, 'BE', 'Vorrangnetz für den Fußverkehr definieren; bei Planung und Instandhaltung prioritär behandeln', '{3604}', 9956, 1, 3, null, 'Bessere Fußwege erleichtern den Weg zu Geschäften, der Bezug zum Einkaufsangebot ist aber indirekt und kaum untersucht. Gut machbar über Landes- und Bezirkshaushalte.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=61', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10051, 36, 14, 'BE', 'Fahrradstraßen parallel zu Hauptstraßen deutlich ausweiten', '{3604}', 9957, 1, 3, null, 'Radkunden kaufen häufig und lokal ein, der Effekt auf Geschäftsbesatz ist aber nur indirekt; Radnetze sind kurzfristig umsetzbar. Wirkung auf Leerstand kaum belegt.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=65', 'https://doi.org/10.1080/01441647.2021.1912849', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10052, 36, 14, 'BE', 'Privat finanzierte Fahrradparkhäuser an stark frequentierten Orten, insbesondere Bahnhöfen', '{3604}', 9958, 1, 3, null, 'Sichere Abstellplätze erleichtern die Anreise mit dem Rad, sind aber nur eine Teilvoraussetzung für die Erreichbarkeit. Günstig und schnell umsetzbar; Wirkung auf Einkaufsangebote kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=65', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10053, 36, 14, 'BE', 'Sonntagsöffnung bundesweit erlauben; Bezirke sollen zusätzliche verkaufsoffene Sonntage genehmigen', '{3604}', 9973, 1, 1, null, 'Volle Freigabe könnte Kunden zusätzlich anziehen; Studien finden mehr Beschäftigung in Europa, aber weniger Handelsjobs in Deutschland, Wirkung auf Schließungen nicht direkt untersucht. Sonntagsschutz (Art. 140 GG) setzt enge Grenzen; teils Bundesrecht nötig.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=21', 'https://edoc.hu-berlin.de/18452/5152', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10054, 36, 14, 'MV', 'Sonntagsöffnungsverbot vollständig aufheben (im Kapitel Tourismus genannt, ohne Innenstadtbezug).', '{3604}', 9973, 1, 1, null, 'Volle Freigabe könnte Kunden zusätzlich anziehen; Studien finden mehr Beschäftigung in Europa, aber weniger Handelsjobs in Deutschland, Wirkung auf Schließungen nicht direkt untersucht. Sonntagsschutz (Art. 140 GG) setzt enge Grenzen; teils Bundesrecht nötig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=19', 'https://edoc.hu-berlin.de/18452/5152', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10055, 36, 14, 'ST', 'Ladenöffnungszeitengesetz weitgehend liberalisieren, mehr Sonntags- und Feiertagsöffnungen ermöglichen', '{3604}', 9973, 1, 1, null, 'Volle Freigabe könnte Kunden zusätzlich anziehen; Studien finden mehr Beschäftigung in Europa, aber weniger Handelsjobs in Deutschland, Wirkung auf Schließungen nicht direkt untersucht. Sonntagsschutz (Art. 140 GG) setzt enge Grenzen; teils Bundesrecht nötig.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=7', 'https://edoc.hu-berlin.de/18452/5152', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10056, 36, 14, 'ST', 'Sichere Fahrradabstellanlagen und Ladepunkte an Bahnhöfen, ÖPNV-Knoten und in Ortszentren', '{3604}', 9958, 1, 3, null, 'Sichere Abstellplätze erleichtern die Anreise mit dem Rad, sind aber nur eine Teilvoraussetzung für die Erreichbarkeit. Günstig und schnell umsetzbar; Wirkung auf Einkaufsangebote kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=66', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10057, 36, 14, 'ST', 'Ortskerne beleben; Innenentwicklung hat Vorrang vor neuem Flächenverbrauch', '{3602}', 9969, 1, 3, null, 'Leitlinien wie Innenentwicklung oder neue Zentrenpläne geben Richtung vor; konkrete Wirkung hängt von späteren Instrumenten ab und ist schwer zu belegen. Rechtlich ohne Hürden.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=58', 'https://repos.hcu-hamburg.de/handle/hcu/570', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10058, 36, 14, 'ST', 'Sicherheitspartnerschaften von Polizei und Ordnungsämtern ausbauen; mehr Polizeipräsenz im öffentlichen Raum', '{3603}', 9975, 1, 2, null, 'Mehr Präsenz kann Kriminalität an Brennpunkten senken und das Sicherheitsgefühl verbessern; der Einfluss auf Passantenfrequenz und Ladenbesatz ist kaum belegt. Personalaufbau dauert.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=47', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356500/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10059, 36, 15, null, 'Versandhandel mit rezeptpflichtigen Medikamenten verbieten', '{3601}', null, 1, 0, null, 'Das Versandverbot würde Apotheken vor Ort im Wettbewerb entlasten, betrifft aber nur ein Segment des Handels. Nach EuGH-Rechtsprechung verstößt ein Verbot gegen die Warenverkehrsfreiheit und ist nicht umsetzbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=29', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10060, 36, 15, null, 'Erhalt und Ausbau innerstädtischer Fahrspuren und Parkraum, zum Schutz des Einzelhandels', '{3604}', 9953, 1, 2, null, 'Gute Pkw-Erreichbarkeit hilft Händlern mit Kundschaft aus dem Umland; Studien zeigen aber, dass viele Kunden zu Fuß, mit Rad oder ÖPNV kommen. Zuständig sind vor allem Kommunen; der Bund setzt nur den Rahmen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=43', 'https://findingspress.org/article/24497-local-business-perception-vs-mobility-behavior-of-shoppers-a-survey-from-berlin', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10061, 36, 15, null, 'Historische Innenstädte bewahren und bei Bedarf rekonstruieren', '{3603}', null, 1, 2, null, 'Historische Stadtbilder können Besucher anziehen, der Zusammenhang mit Geschäftsschließungen ist kaum untersucht. Der Bund kann nur über Förderung und Denkmalprogramme beitragen, Rekonstruktionen sind teuer.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=172', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10062, 36, 15, 'BE', 'Personaloffensive für den Berliner Nahverkehr', '{3604}', 9959, 1, 2, null, 'Bessere Anbindung bringt Kunden in die Zentren; ÖPNV-Kunden kommen öfter, geben je Besuch nach Kontrolle von Kundenmerkmalen aber kaum anders aus. Der Effekt auf Geschäftsbesatz ist kaum belegt. Netzausbau braucht Jahre und hohe Mittel, Personal fehlt teils.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=41', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10063, 36, 15, 'BE', 'Ausbau des Schienennetzes und Einsatz neuer Verkehrssysteme wie Seilbahnen', '{3604}', 9959, 1, 2, null, 'Bessere Anbindung bringt Kunden in die Zentren; ÖPNV-Kunden kommen öfter, geben je Besuch nach Kontrolle von Kundenmerkmalen aber kaum anders aus. Der Effekt auf Geschäftsbesatz ist kaum belegt. Netzausbau braucht Jahre und hohe Mittel, Personal fehlt teils.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=42', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10064, 36, 15, 'BE', 'ÖPNV-Anbindungen neuer Stadtgebiete vor deren Bezug fertigstellen', '{3604}', 9959, 1, 2, null, 'Bessere Anbindung bringt Kunden in die Zentren; ÖPNV-Kunden kommen öfter, geben je Besuch nach Kontrolle von Kundenmerkmalen aber kaum anders aus. Der Effekt auf Geschäftsbesatz ist kaum belegt. Netzausbau braucht Jahre und hohe Mittel, Personal fehlt teils.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=42', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10065, 36, 15, 'BE', 'Beschleunigung des ÖPNV durch Vorrangschaltungen', '{3604}', 9959, 1, 2, null, 'Bessere Anbindung bringt Kunden in die Zentren; ÖPNV-Kunden kommen öfter, geben je Besuch nach Kontrolle von Kundenmerkmalen aber kaum anders aus. Der Effekt auf Geschäftsbesatz ist kaum belegt. Netzausbau braucht Jahre und hohe Mittel, Personal fehlt teils.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=42', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10066, 36, 15, 'BE', 'Digitale Zugleittechnik zur Erhöhung der Taktfolge', '{3604}', 9959, 1, 2, null, 'Bessere Anbindung bringt Kunden in die Zentren; ÖPNV-Kunden kommen öfter, geben je Besuch nach Kontrolle von Kundenmerkmalen aber kaum anders aus. Der Effekt auf Geschäftsbesatz ist kaum belegt. Netzausbau braucht Jahre und hohe Mittel, Personal fehlt teils.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=42', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10067, 36, 15, 'BE', 'Barrierefreiheit für Mobilitätseingeschränkte und kognitiv Beeinträchtigte ausbauen', '{3604}', 9956, 1, 3, null, 'Bessere Fußwege erleichtern den Weg zu Geschäften, der Bezug zum Einkaufsangebot ist aber indirekt und kaum untersucht. Gut machbar über Landes- und Bezirkshaushalte.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=42', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10068, 36, 15, 'BE', 'Tarifangebote für Pendler aus dem Umland zum Umstieg auf den ÖPNV', '{3604}', 9960, 1, 3, null, 'Einfachere Tickets und Pendlertarife senken Hürden für die Anreise in Zentren; der Beitrag zum Einkaufsangebot bleibt gering und ist kaum untersucht. Landesweit rasch umsetzbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=42', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10069, 36, 15, 'BE', 'Mobilitätskonten mit vereinfachtem Ticketing für ÖPNV, Carsharing und Mikromobilität', '{3604}', 9960, 1, 3, null, 'Einfachere Tickets und Pendlertarife senken Hürden für die Anreise in Zentren; der Beitrag zum Einkaufsangebot bleibt gering und ist kaum untersucht. Landesweit rasch umsetzbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=42', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10070, 36, 15, 'BE', 'Systematische Sanierung der Gehwege im Programm „Gehweg 2030“', '{3604}', 9956, 1, 3, null, 'Bessere Fußwege erleichtern den Weg zu Geschäften, der Bezug zum Einkaufsangebot ist aber indirekt und kaum untersucht. Gut machbar über Landes- und Bezirkshaushalte.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=43', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10071, 36, 15, 'BE', 'Vermeidung von Engstellen auf Gehwegen durch abgestellte Fahrzeuge und Stadtmöbel', '{3604}', 9956, 1, 3, null, 'Bessere Fußwege erleichtern den Weg zu Geschäften, der Bezug zum Einkaufsangebot ist aber indirekt und kaum untersucht. Gut machbar über Landes- und Bezirkshaushalte.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=44', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10072, 36, 15, 'BE', 'Bedarfsgerechter Radwegeausbau durch besseres Radverkehrsmonitoring', '{3604}', 9957, 1, 3, null, 'Radkunden kaufen häufig und lokal ein, der Effekt auf Geschäftsbesatz ist aber nur indirekt; Radnetze sind kurzfristig umsetzbar. Wirkung auf Leerstand kaum belegt.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=43', 'https://doi.org/10.1080/01441647.2021.1912849', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10073, 36, 15, 'BE', 'Radverkehrsführung auf Nebenstraßen parallel zu Hauptstraßen', '{3604}', 9957, 1, 3, null, 'Radkunden kaufen häufig und lokal ein, der Effekt auf Geschäftsbesatz ist aber nur indirekt; Radnetze sind kurzfristig umsetzbar. Wirkung auf Leerstand kaum belegt.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=43', 'https://doi.org/10.1080/01441647.2021.1912849', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10074, 36, 15, 'BE', 'Programm mit abschließbaren Fahrradabstellanlagen', '{3604}', 9958, 1, 3, null, 'Sichere Abstellplätze erleichtern die Anreise mit dem Rad, sind aber nur eine Teilvoraussetzung für die Erreichbarkeit. Günstig und schnell umsetzbar; Wirkung auf Einkaufsangebote kaum untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=43', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10075, 36, 15, 'BE', 'Streusalz auf Gehwegen bei Glätte erlauben und Straßenreinigungsgesetz novellieren', '{3604}', 9956, 1, 3, null, 'Bessere Fußwege erleichtern den Weg zu Geschäften, der Bezug zum Einkaufsangebot ist aber indirekt und kaum untersucht. Gut machbar über Landes- und Bezirkshaushalte.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=84', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10076, 36, 15, 'BE', 'Ordnungsämter rund um die Uhr aktiv, konsequente Ahndung von Verursachern', '{3603}', 9976, 1, 3, null, 'Konsequente Kontrolle kann Verschmutzung verringern und Aufenthaltsqualität steigern; Wirkung auf Einkaufsangebote nur indirekt und kaum untersucht. Mit Personalmitteln im Land machbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=83', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356497/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10077, 36, 15, 'BE', 'Mobile Einsatzteams zur Beseitigung von Müll, Graffiti und Verwahrlosung', '{3603}', 9977, 2, 3, null, 'Sauberkeit gehört zu den meistgenannten Handlungsfeldern im Stadtbild, direkter Ansatz an der Aufenthaltsqualität; Belege zu Frequenz und Umsatz sind begrenzt. Über Landes- und Bezirksmittel gut machbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=83', 'https://pubmed.ncbi.nlm.nih.gov/41926728/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10078, 36, 15, 'BE', 'Videoüberwachung an Müll-Hotspots', '{3603}', 9976, 1, 3, null, 'Konsequente Kontrolle kann Verschmutzung verringern und Aufenthaltsqualität steigern; Wirkung auf Einkaufsangebote nur indirekt und kaum untersucht. Mit Personalmitteln im Land machbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=83', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356497/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10079, 36, 15, 'BE', 'Ausreichende Abfallbehälter und Müll-Infrastruktur', '{3603}', 9977, 2, 3, null, 'Sauberkeit gehört zu den meistgenannten Handlungsfeldern im Stadtbild, direkter Ansatz an der Aufenthaltsqualität; Belege zu Frequenz und Umsatz sind begrenzt. Über Landes- und Bezirksmittel gut machbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=84', 'https://pubmed.ncbi.nlm.nih.gov/41926728/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10080, 36, 15, 'BE', 'Schnellere Entfernung von Autowracks, höhere Kosten für Verursacher', '{3603}', 9976, 1, 3, null, 'Konsequente Kontrolle kann Verschmutzung verringern und Aufenthaltsqualität steigern; Wirkung auf Einkaufsangebote nur indirekt und kaum untersucht. Mit Personalmitteln im Land machbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=83', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356497/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10081, 36, 15, 'BE', 'Entfernung von Obdachlosencamps nach klaren Regeln', '{3603}', 9982, 1, 3, null, 'Räumung ändert das Stadtbild sofort; eine Studie aus Denver sieht leicht weniger Kriminalität im Umkreis, aber mehr Gewaltdelikte und Gesundheitsschäden für Betroffene. Wirkung auf Einkaufsangebote nicht untersucht. Landes- und Ordnungsrecht reicht aus.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=83', 'https://pubmed.ncbi.nlm.nih.gov/39412580/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10082, 36, 15, 'BE', 'Einbindung von Bürgern und Bildungseinrichtungen in Sauberkeitsmaßnahmen', '{3603}', 9978, 1, 3, null, 'Aktionen stärken Bewusstsein und lokale Pflege, ersetzen aber keine dauerhafte Reinigung. Günstig und sofort umsetzbar; Wirkung kaum untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=84', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10083, 36, 15, 'BE', 'Originalgetreue Rekonstruktion stadtbildprägender Bauwerke, u. a. Altstadt am Molkenmarkt', '{3603}', 9980, 1, 2, null, 'Attraktive Stadtbilder können Besucher anziehen, der Zusammenhang mit Geschäftsschließungen ist kaum untersucht. Rekonstruktionen sind teuer und dauern Jahre.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=88', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10084, 36, 15, 'MV', 'Ladenschlusszeiten und Bäderverkaufsverordnung liberalisieren, mehr verkaufsoffene Sonntage, mehr touristische Orte in der Bäderverkaufsverordnung', '{3604}', 9972, 1, 3, null, 'Mehr Sonntagsöffnung kann Frequenz steigern; Länderstudien finden mehr Beschäftigung und Ausgaben, für Deutschland weniger Handelsjobs nach der Liberalisierung. Wirkung auf Schließungen nicht direkt untersucht. Landesrecht, rasch änderbar; Beschäftigtenschutz beachten.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=13', 'https://cep.lse.ac.uk/pubs/download/dp1336.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10085, 36, 15, 'MV', 'Förderung von Sanierung und Umbau von Leerständen, damit daraus neuer Wohnraum entsteht', '{3602}', 9964, 2, 3, null, 'Förderung senkt Umbaukosten und aktiviert Leerstand; Evaluierungen ähnlicher Programme zeigen Aufwertung, aber nicht immer weniger Leerstand. Finanzierbar im Landeshaushalt, auch mit Bundesmitteln.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=90', 'https://www.staedtebaufoerderung.info/SharedDocs/downloads/DE/WeitereProgramme/AktiveStadtUndOrtsteilzentren/Zwischeneva_2015.pdf?__blob=publicationFile&v=2', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10086, 36, 15, 'MV', 'Bei öffentlichen Bauten soll auf einen architektonischen Heimatstil geachtet werden', '{3603}', 9980, 1, 2, null, 'Attraktive Stadtbilder können Besucher anziehen, der Zusammenhang mit Geschäftsschließungen ist kaum untersucht. Rekonstruktionen sind teuer und dauern Jahre.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=89', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10087, 36, 15, 'ST', 'Kredite zu Sonderkonditionen für die Sanierung von Altbauten in historischen Innenstadtbereichen ermöglichen.', '{3603}', 9980, 1, 2, null, 'Attraktive Stadtbilder können Besucher anziehen, der Zusammenhang mit Geschäftsschließungen ist kaum untersucht. Rekonstruktionen sind teuer und dauern Jahre.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=58', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10088, 36, 15, 'ST', 'Ortsumfahrungen schneller realisieren, um die Ortskerne zu entlasten.', '{3603}', null, 1, 2, null, 'Weniger Durchgangsverkehr kann den Ortskern aufwerten, Erfahrungen zeigen aber auch Kaufkraftverlust durch weniger Passanten. Planung und Bau dauern Jahre, teils Bundes- und Kreisstraßen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=198', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10089, 36, 16, null, 'Innenstädte autofrei machen, mit Ausnahmen für Menschen mit besonderen Bedarfen und den Lieferverkehr.', '{3604,3603}', null, 2, 2, null, 'Autofreie Zentren steigern oft Aufenthaltsqualität und Fußgängerfrequenz; Händler befürchten Umsatzverluste und Erreichbarkeitsprobleme, Ausnahmen für Lieferung mindern das. Entscheiden müssen Kommunen, der Bund setzt Verkehrsrecht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=44', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10090, 36, 16, null, 'Hilfsangebote und Sozialarbeit für Obdachlose und Suchtabhängige statt Verdrängung aus den Innenstädten.', '{3603}', null, 1, 2, null, 'Sozialarbeit und Hilfen verringern Konflikte im öffentlichen Raum nachhaltiger als Verdrängung, der Effekt auf Einkaufsangebote ist aber indirekt und kaum untersucht. Zuständig sind Länder und Kommunen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=48', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10091, 36, 16, null, 'Leerstehendes Gewerbe wie Einkaufszentren und Warenhäuser in kommunale oder genossenschaftliche Hand überführen und zu Sorgezentren umbauen.', '{3602}', null, 1, 2, null, 'Öffentliche Übernahme sichert Nachnutzung großer Leerstandsobjekte, ist aber teuer und betrifft wenige Standorte; Erfahrungen mit Sorgezentren fehlen. Bund kann nur mit Programmen und Geld beitragen, Umsetzung liegt bei Kommunen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10092, 36, 16, 'BE', 'Leer gefallene Shoppingcenter in die öffentliche Hand überführen und gemeinschaftlich als Quartiers-Sorgezentren betreiben.', '{3602}', null, 1, 2, null, 'Öffentliche Übernahme sichert Nachnutzung großer Leerstandsobjekte, ist aber teuer und betrifft nur wenige Standorte; Erfahrungen mit kommunalen Sorgezentren fehlen weitgehend. Finanzierung und Erwerb sind aufwendig.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=43', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10093, 36, 16, 'BE', 'Keine neuen Shopping-Center genehmigen, um Kleingewerbe vor Verdrängung zu schützen.', '{3602}', null, 1, 2, null, 'Begrenzung neuer Shopping-Center kann Kleingewerbe und Zentren schützen (Zentrenverträglichkeit), löst bestehenden Leerstand aber nicht. Genehmigung liegt bei den Kommunen, Land kann nur über Planungsrecht lenken.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=50', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10094, 36, 16, 'BE', 'Leerstehende Bürogebäude umnutzen, mit Bundesfördermitteln und einem neuen Landesförderprogramm.', '{3602}', 9964, 2, 3, null, 'Förderung senkt Umbaukosten und aktiviert Leerstand; Evaluierungen ähnlicher Programme zeigen Aufwertung, aber nicht immer weniger Leerstand. Finanzierbar im Landeshaushalt, auch mit Bundesmitteln.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=49', 'https://www.staedtebaufoerderung.info/SharedDocs/downloads/DE/WeitereProgramme/AktiveStadtUndOrtsteilzentren/Zwischeneva_2015.pdf?__blob=publicationFile&v=2', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10095, 36, 16, 'BE', 'Ein Leerstandskataster zur systematischen Erfassung von Leerstand einführen.', '{3602}', 9967, 1, 3, null, 'Bessere Daten erleichtern gezielte Ansiedlung und Ansprache von Eigentümern, bewirken allein aber keine Nutzung. Geringer Aufwand, Ergebnis hängt von der Nutzung der Daten ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=49', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10096, 36, 16, 'BE', 'Bundesgesetz gegen Gewerbeleerstand (Zweckentfremdungsverbot für Gewerbe) fordern, um Leerstand zu sanktionieren.', '{3602}', null, 1, 1, null, 'Sanktionen gegen Gewerbeleerstand könnten Eigentümer zur Vermietung drängen; Erfahrungen mit Gewerbe sind kaum vorhanden. Land kann nur über den Bundesrat anstoßen, Eigentumsrechte sind eine Hürde.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=49', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10097, 36, 16, 'BE', 'Stadtentwicklungsplan Zentren neu auflegen, Zentren als Daseinsvorsorge verstehen.', '{3602}', 9969, 1, 3, null, 'Leitlinien wie Innenentwicklung oder neue Zentrenpläne geben Richtung vor; konkrete Wirkung hängt von späteren Instrumenten ab und ist schwer zu belegen. Rechtlich ohne Hürden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=50', 'https://repos.hcu-hamburg.de/handle/hcu/570', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10098, 36, 16, 'BE', 'Über den Bundesrat eine dauerhafte gesetzliche Begrenzung der Gewerbemieten vorschlagen.', '{3602}', 9963, 1, 1, null, 'Mietbegrenzung kann Verdrängung kleiner Läden bremsen, könnte aber das Angebot an Gewerberaum verknappen; Erfahrungen sind kaum untersucht. Land kann nur im Bundesrat vorschlagen, Eigentumsgarantie ist zu beachten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=89', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10099, 36, 16, 'BE', 'Erhalt der Galeria-Warenhaus-Standorte in der City West, behutsame Weiterentwicklung mit Beteiligung.', '{3602}', 9971, 1, 2, null, 'Warenhaus-Schließungen senken die Frequenz im Umfeld (Studie: im Mittel rund 12 %), Nachnutzungen mildern den Rückgang; die Wirkung kultureller oder öffentlicher Nutzer ist kaum untersucht. Landesmittel sind begrenzt, Eigentümer und Betreiber entscheiden mit.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=48', 'https://doi.org/10.1016/j.jretai.2026.05.001', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10100, 36, 16, 'BE', 'Am Alexanderplatz einen Nutzungsmix (vor allem Kultur) und eine ansprechende Gestaltung ermöglichen, damit der Platz wieder Aufenthaltsqualität hat.', '{3602,3603}', 9981, 2, 2, null, 'Umgestaltungen erhöhen Verweildauer und Frequenz, Erfahrungen aus Fußgängerzonen und Plätzen sind überwiegend positiv, aber vom Einzelfall abhängig. Planung und Bau dauern mehrere Jahre.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=47', 'https://discovery.ucl.ac.uk/1575499/1/Street%20appeal%20%28progress%20in%20planning%29%20-%20revised.pdf', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10101, 36, 16, 'BE', 'Die Zentrale Landesbibliothek soll in das Galeria-Warenhaus am Alexanderplatz einziehen.', '{3602}', 9971, 1, 2, null, 'Warenhaus-Schließungen senken die Frequenz im Umfeld (Studie: im Mittel rund 12 %), Nachnutzungen mildern den Rückgang; die Wirkung kultureller oder öffentlicher Nutzer ist kaum untersucht. Landesmittel sind begrenzt, Eigentümer und Betreiber entscheiden mit.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=47', 'https://doi.org/10.1016/j.jretai.2026.05.001', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10102, 36, 16, 'BE', 'Die kulturelle Nutzung leerstehender Immobilien erleichtern und Zwischennutzungen ausweiten.', '{3602}', 9961, 2, 3, null, 'Pop-up-Läden und Zwischennutzungen beleben Leerstand und können Dauermieter anziehen; viele bleiben aber befristet und lösen strukturellen Leerstand nicht. Rechtlich und finanziell gut machbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=238', 'https://www.innenstadtprogramm.bund.de/SharedDocs/downloads/Webs/ZIZ/DE/Erfahrungsbericht_Zwischennutzung.pdf?__blob=publicationFile&v=4', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10103, 36, 16, 'BE', 'Fahr- und Stellflächen für den Autoverkehr reduzieren, besonders in Einkaufsstraßen, für mehr Platz und Aufenthalt für Fußgänger*innen.', '{3603,3604}', 9955, 2, 3, null, 'Mehr Platz und Aufenthalt für Fußgänger erhöht oft die Passantenfrequenz; Ladenbetreiber befürchten jedoch Umsatzverluste, wenn Parkplätze und Zufahrt wegfallen. Mit Lieferzonen und Baukasten lässt sich der Zugang sichern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=66', 'https://doi.org/10.1080/01441647.2021.1912849', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10104, 36, 16, 'BE', 'Die Zahl der verkaufsoffenen Sonntage reduzieren; eine Aufweichung des Sonntagsöffnungsverbots lehnen wir ab.', '{3604}', null, 0, 3, null, 'Weniger verkaufsoffene Sonntage verkürzen die Öffnungszeiten des stationären Handels und wirken dem Ziel entgegen; Studien zeigen allenfalls geringe Effekte der Sonntagsöffnung. Landesrecht, leicht umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=95', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10105, 36, 16, 'MV', 'Stadtprofile stärken und Innenstädte als lebendige Orte sichern (Grenzfall: Ansiedlung/Nutzungsmischung oder Aufenthalt)', '{3602,3603}', 9969, 1, 3, null, 'Leitlinien wie Innenentwicklung oder neue Zentrenpläne geben Richtung vor; konkrete Wirkung hängt von späteren Instrumenten ab und ist schwer zu belegen. Rechtlich ohne Hürden.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=26', 'https://repos.hcu-hamburg.de/handle/hcu/570', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10106, 36, 16, 'ST', 'Stadtumbauprogramm bis 2035 gegen Leerstand: Rückbau und Aufwertung im Bestand finanzieren.', '{3602,3603}', 9964, 2, 3, null, 'Förderung senkt Umbaukosten und aktiviert Leerstand; Evaluierungen ähnlicher Programme zeigen Aufwertung, aber nicht immer weniger Leerstand. Finanzierbar im Landeshaushalt, auch mit Bundesmitteln.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=85', 'https://www.staedtebaufoerderung.info/SharedDocs/downloads/DE/WeitereProgramme/AktiveStadtUndOrtsteilzentren/Zwischeneva_2015.pdf?__blob=publicationFile&v=2', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10107, 36, 17, null, 'Sichere Radwege in der Innenstadt schaffen, zusammen mit attraktivem öffentlichem Nah- und Fernverkehr.', '{3604}', null, 1, 2, null, 'Sichere Radwege und guter ÖPNV erleichtern die Anreise, der Zusammenhang mit Geschäftsbesatz ist indirekt. Zuständig sind Länder und Kommunen; der Bund kann über Programme beitragen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=30', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10108, 36, 17, 'MV', 'Standort- und Innenstadtpolitik, die inhabergeführte Geschäfte stärkt, Leerstand reduziert und kleinteilige Versorgungsstrukturen erhält.', '{3602}', 9969, 1, 3, null, 'Leitlinien wie Innenentwicklung oder neue Zentrenpläne geben Richtung vor; konkrete Wirkung hängt von späteren Instrumenten ab und ist schwer zu belegen. Rechtlich ohne Hürden.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=33', 'https://repos.hcu-hamburg.de/handle/hcu/570', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10109, 36, 17, 'ST', 'Mehr sichtbare Polizeipräsenz für sichere, attraktive öffentliche Räume', '{3603}', 9975, 1, 2, null, 'Mehr Präsenz kann Kriminalität an Brennpunkten senken und das Sicherheitsgefühl verbessern; der Einfluss auf Passantenfrequenz und Ladenbesatz ist kaum belegt. Personalaufbau dauert.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=67', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356500/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10110, 36, 17, 'ST', 'Ausreichende Mittel für attraktive Innenstädte und lebenswerte Quartiere', '{3603}', null, 1, 2, null, 'Allgemeine Mittelzusage ohne Verwendungszweck; Wirkung hängt vom Einsatz ab und ist nicht abschätzbar. Finanzierung im Landeshaushalt nicht festgelegt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=67', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10111, 36, 17, 'ST', 'Konsequente Nutzung kommunaler Vorkaufsrechte gegen Leerstand und Spekulation im Rahmen der Gemeindeentwicklung', '{3602}', 9962, 1, 2, null, 'Druck auf untätige Eigentümer kann Nutzung anstoßen; Erfahrungen mit Leerstandsabgaben für Gewerbe sind uneinheitlich. Eigentumsrecht und Rechtssicherheit erfordern Aufwand, Vorkaufsrechte sind teuer.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=34', 'https://wrap.warwick.ac.uk/id/eprint/171874/', 'gemischt', '2026-10-14', false, true, 'blind');

